/* ============================================================
   Script      : DLA_05_QUEUE_SAMPLE_INVOICE.sql
   Project     : Document Loading Agent (DLA) - Phase 2
   Environment : DEV (GHAPEXAPPS_ATP_DEV) - do NOT run on PRD
   Changes     : YES - inserts one row in DLA_DOCUMENTS (sample
                 invoice 1) and one PENDING row in
                 DLA_EXTRACTIONS, so the relay has work to do.
   Purpose     : Test the relay end to end before the APEX upload
                 page exists. The long lines of letters below are
                 the file samples/invoices/
                 DLA_01_clean_prairie_fastener.png written as
                 text (base64), so the script can load it without
                 an upload page.
   Schema      : WKSP_WKSPPRDWORKSPACE (workspace DEV_WORKSPACE)
   Run as      : WKSP_WKSPPRDWORKSPACE or ADMIN, SQL Developer,
                 F5 (Run Script)
   Run after   : DLA_04_RELAY_DATABASE.sql
   Re-runnable : yes - each run queues the sample invoice again
   Author      : Claude for Gary D. Hall
   Date        : 11/19/2026
   ============================================================ */

SET DEFINE OFF
SET SERVEROUTPUT ON

ALTER SESSION SET CURRENT_SCHEMA = WKSP_WKSPPRDWORKSPACE;

/* ------------------------------------------------------------
   Block   : Load the sample invoice and queue it
   Purpose : Builds the image from text, inserts the document,
             and calls DLA_RELAY_PKG.QUEUE_EXTRACTION. Rolls back
             and re-raises on any failure.
   ------------------------------------------------------------ */
DECLARE
    l_b64            CLOB;
    l_blob           BLOB;
    l_document_id    NUMBER;
    l_extraction_id  NUMBER;

    PROCEDURE add (p_text IN VARCHAR2) IS
    BEGIN
        DBMS_LOB.WRITEAPPEND(l_b64, LENGTH(p_text), p_text);
    END add;
BEGIN
    DBMS_LOB.CREATETEMPORARY(l_b64, TRUE);

    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');
    add('');

    l_blob := APEX_WEB_SERVICE.CLOBBASE642BLOB(l_b64);

    INSERT INTO dla_documents (
        file_name,
        mime_type,
        file_blob,
        file_size
    ) VALUES (
        'DLA_01_clean_prairie_fastener.png',
        'image/png',
        l_blob,
        DBMS_LOB.GETLENGTH(l_blob)
    )
    RETURNING document_id INTO l_document_id;

    l_extraction_id := dla_relay_pkg.queue_extraction(l_document_id);

    COMMIT;

    DBMS_OUTPUT.PUT_LINE('Document ' || l_document_id || ' loaded, ' || DBMS_LOB.GETLENGTH(l_blob) || ' bytes (expect 97950).');
    DBMS_OUTPUT.PUT_LINE('Extraction ' || l_extraction_id || ' is PENDING. Start the relay to read it.');
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        DBMS_OUTPUT.PUT_LINE('FAILED: ' || SQLERRM);
        RAISE;
END;
/
